import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`med-spa-marketing-audit`,hasInputUrl:!0,heroTitle:`Build a growth plan for your med spa.`,heroSubtitle:`Perplexity Computer audits your funnel, checks your local visibility, and builds your booking plan — automatically.`,heroCta:`Audit My Med Spa`,inputUrlCta:`Audit My Med Spa`,inputUrlPlaceholder:`Your med spa's website`,inputUrlPrefill:`Run a marketing audit for this med spa: {url}. 1) Audit the website and booking flow for friction that loses clients. 2) Check local SEO, reviews, and map-pack visibility. 3) Review the service and pricing presentation against two local competitors. 4) Identify the highest-intent treatments to advertise. 5) Build a 90-day plan to grow bookings, ranked by impact.`,heroOverlaySteps:[`Find the booking-flow friction that loses clients`,`Check your reviews, profile, and map-pack visibility`,`Show how local rivals win the bookings you're missing`,`A funnel audit — ready to use`],generatingSteps:[`Visiting {url} to get started`,`Designing an agent for your task`,`Configuring the analysis`,`Setting up your deliverable`],featureSectionTitle:`From empty slots to a full calendar`,featureCardTitles:[`Connects to your marketing stack`,`Outputs that fill your calendar`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Search Console, Google Analytics, Ahrefs, Google Sheets — Computer audits visibility and builds the plan in the tools you already use.`,`A funnel audit. A local SEO report. A competitor comparison. A 90-day booking plan.`],capabilitySectionTitle:`Your marketing analyst, on autopilot`,capabilitySectionSubtitle:`Paste your med spa's URL, step away, and come back to an audit and a booking plan.`,capabilityCards:[{title:`Funnel Audit`,description:`Computer can find the booking-flow friction that loses clients.`},{title:`Local SEO Check`,description:`Computer can check your reviews, profile, and map-pack visibility.`},{title:`Competitor Compare`,description:`Computer can show how local rivals win the bookings you're missing.`},{title:`Connect Your Tools`,description:`Computer can pull data from Search Console, Analytics, and Ahrefs into Sheets.`},{title:`Remembers Your Spa`,description:`Computer can remember your services and track booking growth over time.`},{title:`Monitor & Alert`,description:`Computer can watch your visibility and flag a competitor's new offer.`}]});export{t as default};
